using Captovix;
int count=0;void Check(bool ok,string title){if(!ok)throw new Exception(title);count++;Console.WriteLine("PASS: "+title);}void Reject(Action f,string title){try{f();}catch(ArgumentException){Check(true,title);return;}catch(System.IO.InvalidDataException){Check(true,title);return;}throw new Exception(title);}
Annotation A(string text,double x,double y)=>new(){Kind=AnnotationKind.Text,Text=text,X1=x,Y1=y,X2=x+60,Y2=y+24,FontSize=20};
AnnotationBox Box(Annotation a)=>new(a.Left,a.Top,a.Width,a.Height);
var label=A("Label",20,30);var button=A("Button",100,30);var panel=new Annotation{Kind=AnnotationKind.Rectangle,X1=10,Y1=10,X2=300,Y2=160};var other=A("Other",400,300);var d=new EditorDocument{OriginalWidth=800,OriginalHeight=600,Annotations=[panel,label,button,other]};
var inner=AnnotationEditing.Group(d,[label.Id,button.Id])!;Check(AnnotationEditing.ExpandGroups(d,[label.Id]).SetEquals([label.Id,button.Id]),"Legacy flat group expands");
var outer=AnnotationEditing.Group(d,[panel.Id,label.Id])!;Check(label.GroupId==inner&&label.GroupPath!.SequenceEqual([outer]),"Nested grouping preserves child group");Check(panel.GroupId==outer&&panel.GroupPath==null,"Panel belongs to outer group");Check(AnnotationEditing.ExpandGroups(d,[label.Id]).SetEquals([panel.Id,label.Id,button.Id]),"Root click selects panel and children");
d.Validate(800,600,"");Check(d.Version==21,"Hierarchy upgrades schema21");var reopened=EditorDocument.Deserialize(d.Serialize());reopened.Validate(800,600,"");Check(reopened.Serialize()==d.Serialize(),"Hierarchy and geometry survive save/reopen");Check(reopened.EditingGroup==null,"Selection scope is not persisted");
d.EditingGroup=outer;Check(AnnotationEditing.ExpandGroups(d,[label.Id]).SetEquals([label.Id,button.Id]),"Entering parent selects child unit");Check(AnnotationEditing.Units(d,[label.Id,panel.Id]).Length==2,"Scoped layout sees panel and child group separately");
d.EditingGroup=inner;Check(AnnotationEditing.ExpandGroups(d,[label.Id]).SetEquals([label.Id]),"Entering child group edits label alone");var bx=button.X1;AnnotationEditing.Align(d,[label.Id,button.Id],AnnotationAlignment.Left,Box);Check(button.X1==label.X1,"Align individual children inside group");Check(panel.X1==10&&other.X1==400,"Child layout leaves parent and unrelated objects intact");
var dup=AnnotationEditing.Duplicate(d,[label.Id],Box);var copy=d.Annotations.Single(a=>dup.Contains(a.Id));Check(copy.GroupId==inner&&copy.GroupPath!.SequenceEqual([outer]),"Duplicate child remains in its existing panel");Check(copy.Id!=label.Id,"Duplicate gets independent object identity");
var clip=AnnotationClipboard.Copy(d,[label.Id]);var pasted=AnnotationClipboard.Paste(d,clip,16,Box);var paste=d.Annotations.Single(a=>pasted.Contains(a.Id));Check(paste.GroupId!=inner&&paste.GroupPath![0]!=outer,"Clipboard remaps full hierarchy without attaching to source panel");d.Validate(800,600,"");
var before=label.FontSize;GroupLayout.ApplyShared(d,[label.Id],"#112233","#AABBCC",32);Check(label.FontSize==32&&label.TextColor=="#112233","Shared text properties target selected child");Check(button.FontSize==before,"Shared property edit respects child scope");var json=d.Serialize();Reject(()=>GroupLayout.ApplyShared(d,[label.Id],"#BAD","",40),"Reject invalid shared color before mutation");Check(d.Serialize()==json,"Invalid shared input is atomic");
var snapshot=d.Snapshot();snapshot.Annotations.First(a=>a.Id==label.Id).GroupPath!.Clear();Check(label.GroupPath!.Count==1,"Snapshot deep copies group ancestry");
d.EditingGroup=null;var session=new EditorSession(d);var initial=d.Serialize();session.Change(doc=>AnnotationEditing.Ungroup(doc,[label.Id]));Check(session.Document.Annotations.First(a=>a.Id==label.Id).GroupId==inner&&session.Document.Annotations.First(a=>a.Id==label.Id).GroupPath==null,"Ungroup parent preserves nested child group");session.Undo();Check(session.Document.Serialize()==initial,"Undo restores hierarchy exactly");session.Redo();Check(session.Document.Annotations.First(a=>a.Id==panel.Id).GroupId==null,"Redo ungroup restores parent state");
var bad=EditorDocument.Deserialize(initial);bad.Annotations.First(a=>a.Id==label.Id).GroupPath=[inner];Reject(()=>bad.Validate(800,600,""),"Reject group cycle");bad=EditorDocument.Deserialize(initial);bad.Annotations.First(a=>a.Id==label.Id).GroupPath=null;Reject(()=>bad.Validate(800,600,""),"Reject inconsistent parent relationship");bad=EditorDocument.Deserialize(initial);bad.Annotations.First(a=>a.Id==label.Id).GroupPath=[label.Id];Reject(()=>bad.Validate(800,600,""),"Reject object identity used as group");
// Mixed panel sizes and grouped leaves distribute as rigid units.
var layout=new EditorDocument{OriginalWidth=800,OriginalHeight=600,Annotations=[A("A",0,30),A("B",150,80),A("C",500,10)]};Check(AnnotationEditing.Distribute(layout,layout.Annotations.Select(a=>a.Id),true,Box),"Distribute three elements");Check(Math.Abs(layout.Annotations[1].Left-layout.Annotations[0].Left-250)<.001,"Equal horizontal gaps retain outer anchors");
d.EditingGroup=inner;button.Locked=true;Check(ObjectControl.CanEdit(d,[label.Id]),"Locked sibling does not block explicit child editing");d.EditingGroup=null;Check(!ObjectControl.CanEdit(d,[label.Id]),"Locked descendant blocks moving entire parent");
Console.WriteLine($"{count} group hierarchy/layout checks passed.");
